css:
* { box-sizing: border-box; }
body { margin: 0; }
#page { width: 320px; }
#g1 { display: grid; width: 300px; grid-template-columns: 100px 1fr; grid-template-rows: 20px; grid-auto-rows: 30px; gap: 10px; }
#a { width: 40px; height: 20px; }
#b { width: 40px; height: 20px; }
#g2 { display: grid; width: 320px; grid-template-columns: repeat(3, 1fr); grid-auto-rows: 25px; gap: 5px 10px; }
#g { grid-column: span 2; }
#g3 { display: grid; width: 260px; grid-template-columns: minmax(60px, 1fr) 80px; grid-template-rows: 20px; row-gap: 4px; }
#i { grid-column: 1; grid-row: 2; height: 20px; }
#j { height: 20px; }
#k { height: 20px; }
#l { grid-column: 2; grid-row: 2; height: 20px; }
#g4 { display: grid; width: 200px; grid-template-columns: auto auto; grid-auto-rows: 18px; }
#m { width: 40px; height: 18px; }
#n { width: 30px; height: 18px; }
